import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useCart } from '../../context/CartContext';
import { ArrowRight, Heart, Headphones, MessageCircle, Package, Search, ShoppingBag, Tag, UserRound } from 'lucide-react';
import orderService from '../../services/orderService';

const currencyFormatter = new Intl.NumberFormat('en-PH', {
    style: 'currency',
    currency: 'PHP',
});

const quickActions = [
    { to: '/dashboard/products', label: 'Browse parts', description: 'Search the catalog', icon: Search },
    { to: '/dashboard/orders', label: 'My purchases', description: 'Track recent orders', icon: Package },
    { to: '/dashboard/messages', label: 'Messages', description: 'Contact marketplace users', icon: MessageCircle },
    { to: '/dashboard/listings', label: 'My listings', description: 'Manage your parts', icon: Tag },
    { to: '/dashboard/wishlist', label: 'Saved parts', description: 'Return to favorites', icon: Heart },
    { to: '/dashboard/support', label: 'Support', description: 'Get help with an order', icon: Headphones },
];

export default function Overview() {
    const { user } = useAuth();
    const { cartItems } = useCart();
    const [orderStats, setOrderStats] = useState({ totalOrders: 0, totalSpent: 0 });
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [refreshKey, setRefreshKey] = useState(0);

    useEffect(() => {
        let mounted = true;

        const fetchDashboardData = async () => {
            setLoading(true);
            setError('');
            try {
                const ordersRes = await orderService.getMyOrders();
                const orders = ordersRes.data?.data?.data || ordersRes.data?.data || [];
                const totalSpent = Array.isArray(orders)
                    ? orders.reduce((sum, order) => sum + (parseFloat(order.total_amount) || 0), 0)
                    : 0;

                if (mounted) {
                    setOrderStats({ totalOrders: Array.isArray(orders) ? orders.length : 0, totalSpent });
                }
            } catch (fetchError) {
                if (mounted) {
                    setError('We could not refresh your order summary. Your other dashboard tools are still available.');
                    console.error('Failed to fetch dashboard data:', fetchError);
                }
            } finally {
                if (mounted) setLoading(false);
            }
        };

        void fetchDashboardData();
        return () => {
            mounted = false;
        };
    }, [refreshKey]);

    const stats = [
        { label: 'Purchases', value: orderStats.totalOrders, icon: Package },
        { label: 'Total spent', value: currencyFormatter.format(orderStats.totalSpent), icon: ShoppingBag },
        { label: 'Items in cart', value: cartItems?.length || 0, icon: ShoppingBag },
    ];

    return (
        <section className="dashboard-overview" aria-labelledby="dashboard-overview-heading">
            <header className="dashboard-overview__header">
                <div>
                    <span className="dashboard-overview__eyebrow">Your CarVex account</span>
                    <h1 id="dashboard-overview-heading">Welcome back, {user?.name?.split(' ')[0] || 'there'}</h1>
                    <p>Keep track of your purchases, saved parts, and seller listings.</p>
                </div>
                <Link to="/dashboard/products" className="dashboard-overview__shop-link">
                    Browse parts <ArrowRight size={16} aria-hidden="true" />
                </Link>
            </header>

            {error ? (
                <div className="dashboard-overview__notice" role="alert">
                    <span>{error}</span>
                    <button type="button" onClick={() => setRefreshKey((key) => key + 1)}>Refresh summary</button>
                </div>
            ) : null}

            <div className="dashboard-overview__stats" aria-busy={loading}>
                {stats.map(({ label, value, icon: Icon }) => (
                    <article className="dashboard-overview__stat" key={label}>
                        <span className="dashboard-overview__stat-icon"><Icon size={18} aria-hidden="true" /></span>
                        <div>
                            <p>{label}</p>
                            <strong>
                                {loading && label !== 'Items in cart'
                                    ? <span className="cv-skeleton-block cv-skeleton-stat" aria-hidden="true" />
                                    : error && label !== 'Items in cart' ? '-' : value}
                            </strong>
                        </div>
                    </article>
                ))}
            </div>

            <section className="dashboard-overview__actions" aria-labelledby="dashboard-actions-heading">
                <div className="dashboard-overview__section-heading">
                    <div>
                        <span>Workspace</span>
                        <h2 id="dashboard-actions-heading">Quick links</h2>
                    </div>
                    <Link to="/dashboard/profile"><UserRound size={15} aria-hidden="true" /> Account profile</Link>
                </div>
                <div className="dashboard-overview__action-grid">
                    {quickActions.map(({ to, label, description, icon: Icon }) => (
                        <Link key={to} to={to} className="dashboard-overview__action">
                            <span><Icon size={18} aria-hidden="true" /></span>
                            <strong>{label}</strong>
                            <small>{description}</small>
                            <ArrowRight size={15} className="dashboard-overview__action-arrow" aria-hidden="true" />
                        </Link>
                    ))}
                </div>
            </section>

            <aside className="dashboard-overview__help">
                <div>
                    <span className="dashboard-overview__help-icon"><Headphones size={19} aria-hidden="true" /></span>
                    <div>
                        <strong>Need a hand?</strong>
                        <p>Contact CarVex support about your account or an order.</p>
                    </div>
                </div>
                <Link to="/dashboard/support">Open support <ArrowRight size={15} aria-hidden="true" /></Link>
            </aside>
        </section>
    );
}
